<script setup lang="ts">
import { reactiveOmit } from '@vueuse/core'
import { ToggleGroupRoot, useForwardPropsEmits } from 'reka-ui'
import { provide } from 'vue'

import type { toggleVariants } from '@/components/ui/toggle'
import type { VariantProps } from 'class-variance-authority'
import type { ToggleGroupRootEmits, ToggleGroupRootProps } from 'reka-ui'
import type { HTMLAttributes } from 'vue'

import { cn } from '@/utils/cn'

type ToggleGroupVariants = VariantProps<typeof toggleVariants>

/**
 * Generated by shadcn-vue, with two repairs. Re-running the CLI drops both.
 *
 * Its own classes, and every rounding and border rule in `ToggleGroupItem`,
 * are written against a `data-horizontal` or `data-vertical` attribute on this
 * root — and two separate things stopped them working.
 *
 * The attribute was never there. `ToggleGroupRoot` renders no `data-*` of its
 * own and only passes `orientation` down to the roving focus, so the size,
 * variant and spacing below are all hand-written; this adds the fourth the
 * classes ask for.
 *
 * And the short variant does not compile. `data-horizontal:` produces no CSS
 * in this build where `data-[horizontal]:` does, so even once the attribute
 * existed the rules stayed dead. Both were needed: with only one of the two,
 * the group is still square-ended with a doubled border down every seam.
 */
const props = withDefaults(defineProps<ToggleGroupRootProps & {
  class?: HTMLAttributes['class']
  variant?: ToggleGroupVariants['variant']
  size?: ToggleGroupVariants['size']
  spacing?: number
}>(), {
  spacing: 0,
})

const emits = defineEmits<ToggleGroupRootEmits>()

provide('toggleGroup', {
  variant: props.variant,
  size: props.size,
  spacing: props.spacing,
})

const delegatedProps = reactiveOmit(props, 'class', 'size', 'variant')
const forwarded = useForwardPropsEmits(delegatedProps, emits)
</script>

<!-- eslint-disable better-tailwindcss/enforce-canonical-classes -- see above: the short form compiles to nothing here -->
<template>
  <ToggleGroupRoot
    v-slot="slotProps"
    data-slot="toggle-group"
    :data-size="size"
    :data-variant="variant"
    :data-spacing="spacing"
    :data-horizontal="orientation === 'vertical' ? undefined : ''"
    :data-vertical="orientation === 'vertical' ? '' : undefined"
    :style="{
      '--gap': spacing,
    }"
    v-bind="forwarded"
    :class="cn('group/toggle-group flex w-fit flex-row items-center gap-[--spacing(var(--gap))] rounded-md data-[spacing=0]:data-[variant=outline]:shadow-xs data-[vertical]:flex-col data-[vertical]:items-stretch', props.class)"
  >
    <slot v-bind="slotProps" />
  </ToggleGroupRoot>
</template>
